// corpus e' o conjunto de nos que exercita cada ramo do formato de fio: os
// quatro formatos de JID, as tres larguras de bloco binario, as duas de lista,
// os dois alfabetos empacotados (com tamanho par e impar), o no' vazio, o
// filtro de atributo vazio e cada tipo Go que o encoder aceita.
//
// Todos os nos tem NO MAXIMO um atributo, de proposito. Attrs e' um map e
// writeAttributes itera sobre ele, entao um no' com dois atributos produz
// bytes em ordem aleatoria e nao serve de golden. Nos com varios atributos sao
// exercitados por round trip, que independe da ordem.
func corpus() []Node {
	return []Node{
		{Tag: "iq", Attrs: Attrs{"id": "1234"}},
		{Tag: "iq", Attrs: Attrs{"to": types.ServerJID}},
		{Tag: "message", Attrs: Attrs{"t": int64(1700000000)}, Content: []byte{0x00, 0x01, 0xFF, 0x7F}},
		{Tag: "message", Attrs: Attrs{"from": types.NewJID("5511999999999", types.DefaultUserServer)}, Content: []byte{0x00, 0x01, 0xFF, 0x7F}},
		{Tag: "presence", Attrs: Attrs{"from": types.NewJID("5511999999999.2:3", types.DefaultUserServer)}},
		{Tag: "list", Attrs: nil, Content: []Node{{Tag: "item", Attrs: Attrs{"jid": types.NewJID("123", types.GroupServer)}}, {Tag: "item", Attrs: Attrs{"n": 7}}}},
		{Tag: "empty", Attrs: Attrs{"skip": ""}},
		{Tag: "nilattr", Attrs: Attrs{"skip": nil}},
		{Tag: "ad", Attrs: Attrs{"jid": types.JID{User: "5511999999999", Device: 12, Server: types.HiddenUserServer}}},
		{Tag: "fb", Attrs: Attrs{"jid": types.JID{User: "999", Device: 3, Server: types.MessengerServer}}},
		{Tag: "interop", Attrs: Attrs{"jid": types.JID{User: "999", Device: 3, Integrator: 42, Server: types.InteropServer}}},
		{Tag: "hosted", Attrs: Attrs{"jid": types.JID{User: "5511", Server: types.HostedServer}}},
		{Tag: "nibble", Attrs: Attrs{"v": "1234567890-.12345"}},
		{Tag: "nibbleeven", Attrs: Attrs{"v": "123456"}},
		{Tag: "hex", Attrs: Attrs{"v": "ABCDEF0123456789A"}},
		{Tag: "raw", Attrs: Attrs{"v": "hello world, não cabe em token"}},
		{Tag: "0"},
		{Tag: "big", Content: []byte(string(make([]byte, 300)))},
		{Tag: "huge", Content: []byte(string(make([]byte, 70000)))},
		{Tag: "b", Attrs: Attrs{"a": true}},
		{Tag: "b", Attrs: Attrs{"b": uint64(18446744073709551615)}},
		{Tag: "b", Attrs: Attrs{"c": int32(-5)}},
		{Tag: "b", Attrs: Attrs{"d": uint32(9)}},
		{Tag: "b", Attrs: Attrs{"e": uint(3)}},
		{Tag: "b", Attrs: Attrs{"f": 42}},
		{Tag: "emptyjid", Attrs: Attrs{"j": types.NewJID("", types.BroadcastServer)}},
	}
}

