func mustMarshal(t *testing.T, n Node) []byte {
	t.Helper()
	data, err := Marshal(n)
	if err != nil {
		t.Fatalf("Marshal(%+v): %v", n, err)
	}
	return data
}

// mustRoundTrip serializa e desserializa o no'. O primeiro byte do frame e' o
// flag de compressao, que Marshal escreve e Unmarshal nao consome.
func mustRoundTrip(t *testing.T, n Node) *Node {
	t.Helper()
	back, err := Unmarshal(mustMarshal(t, n)[1:])
	if err != nil {
		t.Fatalf("Unmarshal do round trip de %+v: %v", n, err)
	}
	return back
}

func TestWireFormatMatchesGoldens(t *testing.T) {
	nodes := corpus()
	if len(nodes) != len(wireGoldens) {
		t.Fatalf("corpus tem %d nos mas ha %d goldens", len(nodes), len(wireGoldens))
	}
	for i, n := range nodes {
		got := hex.EncodeToString(mustMarshal(t, n))
		if got != wireGoldens[i] {
			t.Errorf("no %d (tag %q): formato de fio mudou\n  esperado: %s\n  obtido:   %s", i, n.Tag, wireGoldens[i], got)
		}
	}
}

func TestCorpusRoundTripsPreservingTag(t *testing.T) {
	for i, n := range corpus() {
		if n.Tag == emptyNodeTag {
			// A tag "0" nao sobrevive ao round trip de proposito: o
			// encoder a substitui por uma lista vazia, que nao e' um
			// no'. Coberto em encoder_node_test.go.
			continue
		}
		back := mustRoundTrip(t, n)
		if back.Tag != n.Tag {
			t.Errorf("no %d: tag esperada %q, obtida %q", i, n.Tag, back.Tag)
		}
	}
}
